The rule staggers maintenance by prioritizing robots with the fewest duties left before their next maintenance, so one robot runs to maintenance while others stay fresh, avoiding simultaneous downtime. Within equal urgency it balances duty counts and hours, and near the horizon end it switches to pure balancing while avoiding maintenance that would not finish in time. New robot types are chosen by their work-to-maintenance and work-to-overhead efficiency, with a small penalty for overshooting the remaining horizon.

```python
def rule(ctx):
    # maximum maintenance time among available robot types
    max_maint = 0.0
    for k in range(len(ctx.types)):
        typ = ctx.types[k]
        if typ is not None:
            m = typ['maintenance_time']
            if m > max_maint:
                max_maint = m
    endgame = (max_maint > 0 and ctx.remaining < max_maint * 1.5)

    def score_robot(r):
        typ = ctx.types[r.type]
        if endgame:
            risk = 0
            if r.duties_left <= 1:
                time_needed = typ['work_time'] + typ['maintenance_time'] + typ['return_travel_time'] + typ['charge_time']
                if ctx.remaining < time_needed:
                    risk = 1
            # balance counts and hours; prefer more duties_left to avoid new maintenance
            return (risk, r.count, r.hours, -r.duties_left)
        else:
            cycle_duties = typ['continue_max_work'] / max(1e-9, typ['single_work_time'])
            W = max(1.0, cycle_duties)
            risk = 0
            if r.duties_left <= 1:
                time_needed = typ['work_time'] + typ['maintenance_time'] + typ['return_travel_time'] + typ['charge_time']
                if ctx.remaining < time_needed:
                    risk = 1
            # stagger maintenance: prefer low duties_left, then balance count/hours
            return (risk, r.duties_left * W + r.count + r.hours * 0.001)

    avail_sorted = sorted(ctx.available, key=lambda r: (score_robot(r), r.idx))
    actions = [("reuse", r) for r in avail_sorted]

    # choose preferred types for opening new robots
    type_scores = []
    for k in range(len(ctx.types)):
        typ = ctx.types[k]
        if typ is None or ctx.left[k] <= 0:
            continue
        maint_ratio = typ['maintenance_time'] / max(1e-9, typ['continue_max_work'])
        overhead = (typ['out_travel_time'] + typ['return_travel_time'] + typ['charge_time']) / max(1e-9, typ['work_time'])
        fit = 0.0
        if ctx.remaining < typ['work_time']:
            fit = (typ['work_time'] - ctx.remaining) / typ['work_time']
        type_scores.append((maint_ratio + overhead + fit, k))
    type_scores.sort()
    new_order = [k for _, k in type_scores]

    new_actions = []
    if new_order:
        best_k = new_order[0]
        new_actions.append(("new", best_k))
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < len(ctx.types) and ctx.left[gt] > 0 and gt != best_k:
            new_actions.append(("new", gt))
        for k in new_order:
            if k != best_k and (gt is None or k != gt):
                new_actions.append(("new", k))
    else:
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < len(ctx.types):
            new_actions.append(("new", gt))
        else:
            new_actions.append(("new", 0))

    actions.extend(new_actions)
    return actions
```

The rule keeps count balance when capacity is comfortable, but as remaining capacity tightens it allows a robot to get ahead by just enough duties to enter maintenance early, staggering maintenance instead of letting robots cluster. It also avoids triggering maintenance near the horizon end, and among equal candidates prefers the robot that has been ready longest so freshly charged robots remain as backup. Alternative reuse options are ordered by load to make genome deviations useful for improving balance.

```python
def rule(ctx):
    avail = list(ctx.available)

    def new_type():
        chosen = ctx.gene_type
        try:
            if chosen < 0 or ctx.left[chosen] <= 0 or ctx.types[chosen] is None:
                for k in range(len(ctx.left)):
                    if ctx.left[k] > 0 and ctx.types[k] is not None:
                        chosen = k
                        break
        except Exception:
            pass
        return chosen

    if not avail:
        return [("new", new_type())]

    min_count = min(r.count for r in avail)

    n_types = len(ctx.types)
    max_maint = 0.0
    sum_work = 0.0
    n_work = 0
    for k in range(n_types):
        typ = ctx.types[k]
        if typ is not None:
            mt = typ.get("maintenance_time", 0.0) or 0.0
            wt = typ.get("work_time", 10.0) or 10.0
            if mt > max_maint:
                max_maint = mt
            sum_work += wt
            n_work += 1

    avg_work = (sum_work / n_work) if n_work > 0 else 10.0
    if avg_work <= 0:
        avg_work = 10.0

    try:
        cap = ctx.capacity
    except Exception:
        cap = ctx.remaining

    slack = cap - ctx.remaining
    buffer = max_maint + 2.0 * avg_work
    if buffer <= 0:
        w = 0.5
    else:
        w = 1.0 - slack / buffer
        if w < 0.0:
            w = 0.0
        if w > 1.0:
            w = 1.0
    if w < 0.2:
        w = 0.2

    prefer_low_duties = (w >= 0.5)

    def key(r):
        typ = ctx.types[r.type] if r.type < n_types else None
        work = avg_work
        mt = max_maint
        if typ is not None:
            work = typ.get("work_time", avg_work) or avg_work
            mt = typ.get("maintenance_time", max_maint) or max_maint
        if work <= 0:
            work = avg_work

        lead = int(math.ceil((mt / work) * w)) if work > 0 else 0
        if lead < 0:
            lead = 0

        late = 0
        if r.duties_left <= 1 and ctx.remaining < mt + work:
            late = 1

        eligible = 0 if r.count <= min_count + lead else 1
        mp = r.duties_left if prefer_low_duties else -r.duties_left

        return (late, eligible, mp, r.count, r.hours, r.ready, r.idx)

    ordered = sorted(avail, key=key)
    first = ordered[0]
    rest = sorted(ordered[1:], key=lambda r: (r.count, r.hours, r.ready, r.idx))

    actions = [("reuse", first)]
    for r in rest:
        actions.append(("reuse", r))
    actions.append(("new", new_type()))
    return actions
