The rule balances duty load primarily by count (with a mild hours term), but when total capacity is insufficient it adaptively staggers maintenance: with few opened robots it lets robots finish their remaining cycle before switching, while with more robots it only does this near the maintenance threshold. Near the horizon it stops staggering to avoid unnecessary maintenance-triggering choices, and new-robot types are ordered by maintenance frequency, travel/charge overhead, and horizon fit.

```python
def rule(ctx):
    max_maint = 0.0
    avg_duty = 0.0
    ntypes = 0
    for k in range(len(ctx.types)):
        typ = ctx.types[k]
        if typ is not None:
            m = typ['maintenance_time']
            if m > max_maint:
                max_maint = m
            w = typ['work_time']
            if w > 0:
                avg_duty += w
                ntypes += 1
    if ntypes > 0:
        avg_duty /= ntypes
    if avg_duty <= 0:
        avg_duty = 10.0

    endgame = (max_maint > 0 and ctx.remaining < max_maint * 1.5)
    relax = (ctx.capacity >= ctx.remaining)

    n_open = len(ctx.robots)
    denom = n_open - 1
    if denom < 1.0:
        denom = 1.0

    def score_robot(r):
        typ = ctx.types[r.type]
        work = typ['work_time']
        if work <= 0:
            work = 1e-9
        single = typ['single_work_time']
        if single <= 0:
            single = 1e-9
        cycle = typ['continue_max_work'] / single
        if cycle < 1.0:
            cycle = 1.0

        load = r.count + r.hours / (avg_duty * 4.0)

        if endgame:
            risk = 0
            if r.duties_left <= 1:
                need = (work + typ['maintenance_time'] +
                        typ['return_travel_time'] + typ['charge_time'])
                if ctx.remaining < need:
                    risk = 1
            return (risk, load, -r.duties_left)

        if relax:
            return (0, load, -r.duties_left)

        maint_shifts = ((typ['maintenance_time'] + typ['charge_time'] +
                         typ['return_travel_time']) / work)
        threshold = maint_shifts / denom
        if threshold < 1.0:
            threshold = 1.0
        if threshold > cycle:
            threshold = cycle

        if r.duties_left <= threshold:
            return (0, r.duties_left * work, load)
        else:
            return (1, load, -r.duties_left)

    avail_sorted = sorted(ctx.available, key=lambda r: (score_robot(r), r.idx))
    actions = [("reuse", r) for r in avail_sorted]

    type_scores = []
    for k in range(len(ctx.types)):
        typ = ctx.types[k]
        if typ is None or ctx.left[k] <= 0:
            continue
        work = typ['work_time']
        if work <= 0:
            work = 1e-9
        cm = typ['continue_max_work']
        if cm <= 0:
            cm = 1e-9

        maint_ratio = typ['maintenance_time'] / cm
        overhead = ((typ['out_travel_time'] + typ['return_travel_time'] +
                     typ['charge_time']) / work)
        fit = 0.0
        if ctx.remaining < work:
            fit = (work - ctx.remaining) / work

        type_scores.append((maint_ratio + overhead + fit, k))

    type_scores.sort()
    new_order = [k for _, k in type_scores]

    new_actions = []
    if new_order:
        best_k = new_order[0]
        new_actions.append(("new", best_k))
        gt = ctx.gene_type
        if (gt is not None and 0 <= gt < len(ctx.types) and
                ctx.left[gt] > 0 and gt != best_k):
            new_actions.append(("new", gt))
        for k in new_order:
            if k != best_k and (gt is None or k != gt):
                new_actions.append(("new", k))
    else:
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < len(ctx.types):
            new_actions.append(("new", gt))
        else:
            new_actions.append(("new", 0))

    actions.extend(new_actions)
    return actions
