The rule uses a horizon-aware, capped maintenance-debt policy: for most of the horizon it prefers robots closer to their next maintenance so maintenance events are staggered, but it caps how far one robot may run ahead of the least-used available robot to keep duty counts balanced. Near the end it switches to preserving robots on their last duty, and in the final shift it purely balances counts/hours. New robot types are ordered by how much useful capacity they add over the remaining horizon with the least wasted overshoot and maintenance burden.

```python
def rule(ctx):
    R = ctx.remaining
    T = ctx.T
    t = ctx.t
    types = ctx.types
    ntypes = len(types)
    robots = ctx.robots if ctx.robots else []

    def params(typ):
        wt = float(typ.get("work_time", 10.0) or 10.0)
        single = float(typ.get("single_work_time", wt) or wt)
        cmax = float(typ.get("continue_max_work", wt) or wt)
        maint = float(typ.get("maintenance_time", 0.0) or 0.0)
        charge = float(typ.get("charge_time", 0.0) or 0.0)
        out = float(typ.get("out_travel_time", 0.0) or 0.0)
        ret = float(typ.get("return_travel_time", 0.0) or 0.0)
        return wt, single, cmax, maint, charge, out, ret

    sum_count = 0
    sum_hours = 0.0
    sum_wt = 0.0
    cnt_wt = 0
    global_min_count = None

    for r in robots:
        sum_count += r.count
        sum_hours += r.hours
        typ = types[r.type] if 0 <= r.type < ntypes else None
        if typ is not None:
            wt0 = float(typ.get("work_time", 10.0) or 10.0)
            sum_wt += wt0
            cnt_wt += 1
        if global_min_count is None or r.count < global_min_count:
            global_min_count = r.count

    if global_min_count is None:
        global_min_count = 0

    avg_wt = sum_wt / cnt_wt if cnt_wt else 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    avail_min_count = None
    for r in ctx.available:
        if avail_min_count is None or r.count < avail_min_count:
            avail_min_count = r.count
    if avail_min_count is None:
        avail_min_count = global_min_count

    max_maint = 0.0
    for typ in types:
        if typ is not None:
            m = float(typ.get("maintenance_time", 0.0) or 0.0)
            if m > max_maint:
                max_maint = m

    final_phase = (R <= 1.1 * avg_wt + 1e-9)
    long_phase = (R > max_maint + 2.0 * avg_wt + 1e-9)

    def score_robot(r):
        typ = types[r.type] if 0 <= r.type < ntypes else None
        if typ is None:
            return (r.count, r.hours, r.idx)

        wt, single, cmax, maint, charge, out, ret = params(typ)
        d = r.duties_left
        if d < 0:
            d = 0

        cycle_duties = cmax / max(single, 1e-6)
        if cycle_duties < 1.0:
            cycle_duties = 1.0

        if final_phase:
            return (r.count + 0.1 * (r.hours / max(avg_wt, 1e-6)), r.idx)

        if long_phase:
            cap = int(0.5 * cycle_duties)
            if cap < 1:
                cap = 1

            excess = r.count - avail_min_count - cap
            if excess < 0:
                excess = 0

            base = 2.0 * d + r.count
            base += 0.02 * (r.hours / max(avg_wt, 1e-6))
            return (excess, base, r.idx)

        after = t + wt + out + ret + charge
        ready_after = after + maint
        risk = 0
        if d <= 1 and ready_after + wt > T + 1e-9:
            risk = 1

        score = r.count - 0.2 * d
        score += 0.05 * (r.hours / max(avg_wt, 1e-6))
        return (risk, score, r.idx)

    avail_sorted = sorted(ctx.available, key=score_robot)

    new_cand = []
    for k, typ in enumerate(types):
        if typ is None or ctx.left[k] <= 0:
            continue

        wt, single, cmax, maint, charge, out, ret = params(typ)
        d = int(cmax / max(single, 1e-6))
        if d < 1:
            d = 1

        inc = wt + out + ret + charge
        if inc <= 0:
            inc = wt if wt > 0 else 1.0

        cycle = d * inc + maint
        if cycle <= 0:
            cycle = inc

        full = int(R / cycle) if R > 0 else 0
        cap = full * d * wt
        rem = R - full * cycle
        if rem > 0:
            pd = int((rem + charge) / inc)
            if pd > d:
                pd = d
            if pd < 0:
                pd = 0
            cap += pd * wt

        eff = cap if cap < R else (R if R > 0 else 0.0)
        overshoot = wt - R
        if overshoot < 0:
            overshoot = 0.0

        maint_ratio = maint / max(d * wt, 1e-6)
        util = (d * wt) / max(cycle, 1e-6)
        new_cand.append((overshoot, -eff, maint_ratio, -util, wt, k))

    new_cand.sort()
    new_actions = [("new", x[5]) for x in new_cand]

    gt = ctx.gene_type
    valid_gt = (gt is not None and 0 <= gt < ntypes
                and types[gt] is not None and ctx.left[gt] > 0)

    if valid_gt:
        if not new_actions:
            new_actions = [("new", gt)]
        elif new_actions[0][1] != gt:
            new_actions = [new_actions[0], ("new", gt)] + [
                a for a in new_actions[1:] if a[1] != gt
            ]
    else:
        if not new_actions:
            for k, typ in enumerate(types):
                if typ is not None and ctx.left[k] > 0:
                    new_actions = [("new", k)]
                    break

    actions = [("reuse", r) for r in avail_sorted]
    actions.extend(new_actions)

    if not actions:
        k = ctx.gene_type
        if not (0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, typ in enumerate(types):
                if typ is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
