The combined rule keeps Rule 1’s maintenance-aware robot scoring and smart new-robot type selection, but also exposes Rule 2’s balanced default choice as the very next deviation option. It uses a per-robot survival threshold instead of a global endgame switch, so it only avoids triggering maintenance when that maintenance would meaningfully eat into the remaining horizon. The action list puts Rule 1’s best robot first, Rule 2’s balanced best second, then fills the remaining reuse options and new-type alternatives.

```python
def rule(ctx):
    n_types = len(ctx.types)
    max_maint = 0.0
    for k in range(n_types):
        typ = ctx.types[k]
        if typ is not None:
            m = typ['maintenance_time']
            if m > max_maint:
                max_maint = m

    def score_robot(r):
        typ = ctx.types[r.type]
        work = typ['work_time']
        maint = typ['maintenance_time']
        travel_charge = typ['out_travel_time'] + typ['return_travel_time'] + typ['charge_time']
        time_needed = work + maint + travel_charge
        risk = 0
        if r.duties_left <= 1 and ctx.remaining < time_needed:
            risk = 1
        cycle = max(1.0, typ['continue_max_work'] / max(1e-9, typ['single_work_time']))
        survival = (ctx.remaining < time_needed + 0.5 * maint)
        if survival:
            return (risk, r.count, r.hours, -r.duties_left, r.idx)
        else:
            w = cycle
            return (risk, r.duties_left * w + r.count + r.hours * 0.001, r.idx)

    primary = sorted(ctx.available, key=lambda r: (score_robot(r), r.idx))
    default_order = list(ctx.available)

    actions = []
    seen = set()

    def add_reuse(r):
        if r.idx not in seen:
            seen.add(r.idx)
            actions.append(("reuse", r))

    if primary:
        add_reuse(primary[0])
    if default_order:
        add_reuse(default_order[0])
    for r in primary:
        add_reuse(r)
    for r in default_order:
        add_reuse(r)

    type_scores = []
    for k in range(n_types):
        typ = ctx.types[k]
        if typ is None or ctx.left[k] <= 0:
            continue
        work = typ['work_time']
        maint = typ['maintenance_time']
        travel_charge = typ['out_travel_time'] + typ['return_travel_time'] + typ['charge_time']
        if ctx.remaining <= typ['continue_max_work']:
            maint_ratio = 0.0
        else:
            maint_ratio = maint / max(1e-9, typ['continue_max_work'])
        overhead = travel_charge / max(1e-9, work)
        fit = 0.0
        if ctx.remaining < work:
            fit = (work - ctx.remaining) / work
        end_penalty = 0.0
        if ctx.remaining < maint * 1.5 + work + travel_charge:
            end_penalty = maint / max(1e-9, ctx.T)
        score = maint_ratio + overhead + fit + end_penalty
        type_scores.append((score, k))
    type_scores.sort()
    new_order = [k for _, k in type_scores]

    new_actions = []
    if new_order:
        best_k = new_order[0]
        new_actions.append(("new", best_k))
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < n_types and ctx.left[gt] > 0 and gt != best_k:
            new_actions.append(("new", gt))
        for k in new_order:
            if k != best_k and (gt is None or k != gt):
