    else:
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < n_types and ctx.left[gt] > 0:
            new_actions.append(("new", gt))
        else:
            new_actions.append(("new", 0))

    actions.extend(new_actions)
    return actions
