            single = 10.0
            cont = 10.0
            maint = 0.0
            out = 0.0
            ret = 0.0
            charge = 0.0
        else:
            w = tp.get("work_time", 10.0) or 10.0
            single = tp.get("single_work_time", w) or w
            cont = tp.get("continue_max_work", single) or single
            maint = tp.get("maintenance_time", 0.0) or 0.0
            out = tp.get("out_travel_time", 0.0) or 0.0
            ret = tp.get("return_travel_time", 0.0) or 0.0
            charge = tp.get("charge_time", 0.0) or 0.0
        if w <= 0.0:
            w = 10.0
        if single <= 0.0:
            single = w
        if cont <= 0.0:
            cont = single
        if maint < 0.0:
            maint = 0.0
        M = int(cont / single)
        if M < 1:
            M = 1
        inc = out + w + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0
        return w, single, cont, maint, out, ret, charge, M, inc

    def cap_calc(w, inc, M, maint, start, d):
        if start >= T:
            return 0.0
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0
        if d <= 0:
            d = M
        n = int((T - start) / inc) + 1
        if n < 0:
            n = 0
        first = d if d < n else n
        cap = first * w
        if first < d:
            return cap
        after = start + d * inc + maint
        if after >= T:
            return cap
        n2 = int((T - after) / inc) + 1
        if n2 < 0:
            n2 = 0
        if n2 > M:
            n2 = M
        cap += n2 * w
        if n2 == M:
            t2 = after + M * inc + maint
            if t2 < T:
                cycle_time = M * inc + maint
                if cycle_time > 0.0:
                    full_cycles = int((T - t2) / cycle_time)
                    if full_cycles > 0:
                        cap += full_cycles * M * w
                        t3 = t2 + full_cycles * cycle_time
                    else:
                        t3 = t2
                    if t3 < T:
