            total = 0.0
            for (r2, w2, inc2, M2, maint2, d2, ready2) in info:
                start = ready2
                if start < t_next:
                    start = t_next
                total += cap_calc(w2, inc2, M2, maint2, start, d2)
            w_cache[w] = total

    scored = []
    for r in available:
