        base_total = w_cache[w]
        base_cand = cap_calc(w, inc, M, maint, t_next, d)
        if uses_last:
            after_start = t + inc + maint
            d_after = M
        else:
            after_start = t + inc
            d_after = d - 1
        actual = cap_calc(w, inc, M, maint, after_start, d_after)
        total_after = base_total - base_cand + actual
        R_after = T - t_next
        if R_after < 0.0:
            R_after = 0.0
        deficit = R_after - total_after
        if deficit < 0.0:
            deficit = 0.0

        load = r.count + r.hours / avg_work
        progress = (M - d) / float(M)
        if progress < 0.0:
            progress = 0.0
        if progress > 1.0:
            progress = 1.0
        maint_flag = 0 if r.first_maint is None else 1

        if end_phase:
            if w >= R - 1e-9:
                fit_flag = 0
                fit_val = w - R
            else:
                fit_flag = 1
                fit_val = -w
        else:
            fit_flag = 0
            fit_val = 0.0

        if avoid_maint:
            trigger = 0 if d > 1 else 1
            key = (fit_flag, fit_val, trigger, deficit, load, -d, maint_flag, r.idx)
        else:
            key = (fit_flag, fit_val, deficit, -progress, maint, load, maint_flag, -d, r.idx)
        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    new_cands = []
    for k in range(ntypes):
        if types[k] is None:
            continue
        if ctx.left[k] <= 0:
            continue
        w, single, cont, maint, out, ret, charge, M, inc = params(k)
        cap_new = cap_calc(w, inc, M, maint, t, M)
        denom = M * inc + maint
        efficiency = (M * w) / denom if denom > 0.0 else 0.0
        maint_ratio = maint / (M * w) if M * w > 0.0 else 0.0
        w_dev = abs(w - avg_work)
        if end_phase:
            if w >= R - 1e-9:
                fit_flag = 0
                fit_val = w - R
            else:
                fit_flag = 1
                fit_val = -w
            new_key = (fit_flag, fit_val, maint_ratio, -efficiency, w_dev, k)
        else:
            new_key = (maint_ratio, -efficiency, -cap_new, w_dev, k)
        new_cands.append((new_key, k))
    new_cands.sort(key=lambda x: x[0])
    new_actions = [("new", k) for _, k in new_cands]

    gt = ctx.gene_type
    valid_gt = (gt is not None and 0 <= gt < ntypes
                and types[gt] is not None and ctx.left[gt] > 0)
    if valid_gt:
        if not new_actions:
            new_actions = [("new", gt)]
        elif new_actions[0][1] != gt:
            rest = [a for a in new_actions[1:] if a[1] != gt]
            new_actions = [new_actions[0], ("new", gt)] + rest
    else:
        if not new_actions:
            for k in range(ntypes):
                if types[k] is not None and ctx.left[k] > 0:
                    new_actions = [("new", k)]
                    break

    actions.extend(new_actions)
    if not actions:
        k = ctx.gene_type
        if not (0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i in range(ntypes):
                if types[i] is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is None:
            k = ctx.gene_type
        actions = [("new", k)]
    return actions
