        else:
            w = cycle
            if n_avail >= 4:
                w = max(2.0, cycle * 0.6)
            elif n_avail == 3:
                w = max(2.0, cycle * 0.8)
            fm_pen = 0.02 if r.first_maint is not None else 0.0
            score = r.duties_left * w + r.count + 0.35 * hours_equiv + fm_pen

        return (risk, score, r.idx)

    primary = sorted(ctx.available, key=robot_key)

    def balance_key(r):
        typ = ctx.types[r.type]
        return (r.count, r.hours / max(1e-9, typ['work_time']), -r.duties_left, r.idx)

    balance = sorted(ctx.available, key=balance_key)

    def fresh_key(r):
        return (-r.duties_left, r.count, r.hours, r.idx)

    fresh = sorted(ctx.available, key=fresh_key)

    actions = []
    seen = set()

    def add_reuse(r):
        if r.idx not in seen:
            seen.add(r.idx)
            actions.append(("reuse", r))

    if primary:
        add_reuse(primary[0])
    if balance:
        add_reuse(balance[0])
    if len(primary) > 1:
        add_reuse(primary[1])
    if fresh:
        add_reuse(fresh[0])
    for r in primary:
        add_reuse(r)
    for r in balance:
        add_reuse(r)
    for r in fresh:
        add_reuse(r)

