        end_penalty = 0.0
        if ctx.remaining < maint * 1.5 + work + travel_charge:
            end_penalty = maint / max(1e-9, ctx.T)

        exist_pen = 0.0
        if ctx.robots and k not in opened:
            exist_pen = 0.05

        score = maint_ratio + overhead + fit + end_penalty + exist_pen
        type_scores.append((score, k))

    type_scores.sort()
    new_order = [k for _, k in type_scores]

    new_actions = []
    seen_new = set()

    def add_new(k):
        if (k is not None and 0 <= k < n_types and
                ctx.types[k] is not None and ctx.left[k] > 0 and
                k not in seen_new):
            seen_new.add(k)
            new_actions.append(("new", k))

