The failure was only the builtin `id()` (unavailable in the sandbox). I replace the identity bookkeeping with the position of each robot in `ctx.available` (a unique per-call token). The heuristic is kept: compute a representative duty length, score each available robot by projected load (`count + hours/avg + this duty`), phase that load against `duties_left` so maintenance cycles are staggered rather than synchronized, hard-penalize robots that would be forced into maintenance inside the remaining horizon, then alternate between a count-balanced order and a budget-first order for the reuse preference list. If no robot is available, estimate each type's remaining duty capacity over the horizon and rank new types by feasibility/capacity/efficiency/limit. Deterministic, O(robots).

```python
def rule(ctx):
    types = ctx.types
    ntypes = len(types) if types is not None else 0
    robots = ctx.robots if ctx.robots is not None else []

    def g(tp, key, default):
        if tp is None:
            return default
        v = tp.get(key, default)
        if v is None:
            return default
        return v

    # Representative duty length for normalising hours against counts.
    if robots:
        s = 0.0
        for r in robots:
            tp = types[r.type] if (types is not None and r.type is not None and 0 <= r.type < ntypes) else None
            w = g(tp, "work_time", 10.0)
            if w is None or w <= 0.0:
                w = 10.0
            s += w
        avg_work = s / len(robots)
    else:
        s = 0.0
        c = 0
        for k in range(ntypes):
            tp = types[k]
            w = g(tp, "work_time", None)
            if w is not None and w > 0.0:
                s += w
                c += 1
        avg_work = s / c if c > 0 else 10.0
    if avg_work <= 0.0:
        avg_work = 10.0

    N = len(robots)
    if N < 1:
        N = 1
    den = N - 1
    if den < 1:
        den = 1

    R = ctx.remaining
    avail = ctx.available if ctx.available is not None else []

    items = []
    for pos, r in enumerate(avail):
        tp = types[r.type] if (types is not None and r.type is not None and 0 <= r.type < ntypes) else None
        w = g(tp, "work_time", 10.0)
        if w is None or w <= 0.0:
            w = 10.0
        out = g(tp, "out_travel_time", 0.0)
        ret = g(tp, "return_travel_time", 0.0)
        charge = g(tp, "charge_time", 0.0)
        single = g(tp, "single_work_time", w)
        if single is None or single <= 0.0:
            single = w
        cont = g(tp, "continue_max_work", single)
        if cont is None or cont <= 0.0:
            cont = single
        maint = g(tp, "maintenance_time", 0.0)
        if maint is None or maint < 0.0:
            maint = 0.0
        if out is None:
            out = 0.0
        if ret is None:
            ret = 0.0
        if charge is None:
            charge = 0.0

        M = int(cont / single + 1e-9) if single > 0.0 else 1
        if M < 1:
            M = 1
        cycle = out + w + ret + charge
        if cycle <= 0.0:
            cycle = w

        cnt = r.count if r.count is not None else 0
        hrs = r.hours if r.hours is not None else 0.0
        dleft = r.duties_left if r.duties_left is not None else M
        if dleft < 0:
            dleft = 0
        if dleft > M:
            dleft = M

        inc = 1.0 + w / avg_work
        post_load = cnt + hrs / avg_work + inc

        will_maint = (dleft <= 1) and (maint > 0.0)
        lost = will_maint and (R < maint + cycle)

        if maint > 0.0 and cycle > 0.0:
            req = maint / (cycle * den)
            L = int(req)
            if L < req - 1e-9:
                L += 1
            if L > M - 1:
                L = M - 1
            if L < 0:
                L = 0
            margin = L * inc
        else:
            margin = 0.0

        spread = M - dleft
        if spread < 0:
            spread = 0
        if spread > M - 1:
            spread = M - 1
        if M > 1 and not lost:
            phase = margin * spread / (M - 1)
        else:
            phase = 0.0

        if lost:
            key_bal = post_load + 1e6
        else:
            key_bal = post_load - phase

        ridx = r.idx if r.idx is not None else pos
        rready = r.ready if r.ready is not None else 0.0
        items.append((key_bal, post_load, dleft, ridx, rready, lost, pos, r))

    # Rank each still-openable robot type by how much capacity it could add.
    def new_scores():
        res = []
        for k in range(ntypes):
            tp = types[k]
            if tp is None:
                continue
            leftk = ctx.left[k] if ctx.left[k] is not None else 0
            if leftk <= 0:
                continue
            w = g(tp, "work_time", 10.0)
            if w is None or w <= 0.0:
                w = 10.0
            single = g(tp, "single_work_time", w)
            if single is None or single <= 0.0:
                single = w
            cont = g(tp, "continue_max_work", single)
            if cont is None or cont <= 0.0:
                cont = single
            out = g(tp, "out_travel_time", 0.0) or 0.0
            ret = g(tp, "return_travel_time", 0.0) or 0.0
            charge = g(tp, "charge_time", 0.0) or 0.0
            maint = g(tp, "maintenance_time", 0.0)
            if maint is None or maint < 0.0:
                maint = 0.0
            M = int(cont / single + 1e-9) if single > 0.0 else 1
            if M < 1:
                M = 1
            cyc = out + w + ret + charge
            if cyc <= 0.0:
                cyc = w
            m = 0
            if R > 0.0 and cyc > 0.0:
                full = M * cyc + maint
                if full <= 0.0:
                    full = M * cyc
                if full > 0.0:
                    q = int(R / full + 1e-9)
                    if q < 0:
                        q = 0
                    rem = R - q * full
                    if rem < 0.0:
                        rem = 0.0
                    rp = int(rem / cyc + 1e-9) if cyc > 0.0 else 0
                    if rp > M:
                        rp = M
                    if rp < 0:
                        rp = 0
                    m = q * M + rp
                if R >= w - 1e-9 and m < 1:
                    m = 1
                if R < w - 1e-9:
                    m = 0
            cap = m * w
            fit = 0 if (R <= 0.0 or w <= R + 1e-9) else 1
            eff = w / cyc if cyc > 0.0 else 0.0
            res.append(((fit, -cap, -eff, -leftk, k), k))
        res.sort()
        return res

    # No robot available now: pick the best new type.
    if not items:
        ns = new_scores()
        if not ns:
            gt = ctx.gene_type
            if gt is None or not (0 <= gt < ntypes):
                gt = 0
            return [("new", gt)]
        best_k = ns[0][1]
        acts = [("new", best_k)]
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < ntypes and gt != best_k and (ctx.left[gt] is None or ctx.left[gt] > 0):
            acts.append(("new", gt))
        for entry in ns:
            k = entry[1]
            if k != best_k and (gt is None or k != gt):
                acts.append(("new", k))
        return acts

    primary = min(items, key=lambda it: (it[0], it[4], it[3]))
    nonlost = [it for it in items if not it[5]]
    losts = [it for it in items if it[5]]

    # A: minimise projected load.  B: preserve budget (earliest maintenance first).
    A = sorted(nonlost, key=lambda it: (it[1], it[3]))
    B = sorted(nonlost, key=lambda it: (-it[2], it[1], it[3]))

    ordered = []
    seen = set()
    ordered.append(primary[7])
    seen.add(primary[6])

    la = len(A)
    lb = len(B)
    steps = la if la > lb else lb
    for s in range(steps):
        if s < la:
            it = A[s]
            if it[6] not in seen:
                seen.add(it[6])
                ordered.append(it[7])
        if s < lb:
            it = B[s]
            if it[6] not in seen:
                seen.add(it[6])
                ordered.append(it[7])

    for it in nonlost:
        if it[6] not in seen:
            seen.add(it[6])
            ordered.append(it[7])

    for it in sorted(losts, key=lambda it: (it[1], it[3])):
        if it[6] not in seen:
            seen.add(it[6])
            ordered.append(it[7])

    for it in items:
        if it[6] not in seen:
            seen.add(it[6])
            ordered.append(it[7])

    actions = [("reuse", r) for r in ordered]

    ns = new_scores()
    if ns:
        best_k = ns[0][1]
        actions.append(("new", best_k))
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < ntypes and gt != best_k and (ctx.left[gt] is None or ctx.left[gt] > 0):
            actions.append(("new", gt))
        for entry in ns:
            k = entry[1]
