I combined Rule 2’s maintenance-avoidance and capacity-reset logic with Rule 1’s incremental variance balancing and capacity-aware new-type selection. The rule first decides whether maintenance resets are needed from total remaining duties; if not, it avoids triggering maintenance and prefers robots with more budget, otherwise it prefers robots closest to maintenance to renew capacity. Within that, it ranks candidates by allowed load slack (to stagger maintenance), danger of losing a robot without a useful return, progress toward maintenance, and an incremental count/hour imbalance cost. New robot types are ranked by estimated remaining capacity coverage, overshoot, fit to the current average duty length, and efficiency.

```python
def rule(ctx):
    types = ctx.types
    ntypes = len(types)
    R = ctx.remaining

    # ---- Average duty length of opened robots (fallback: all types) ----
    sumw = 0.0
    nw = 0
    for r in ctx.robots:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is not None:
            w = tp.get("work_time", 10.0)
            if w is None:
                w = 10.0
            if w > 0.0:
                sumw += w
                nw += 1
    if nw == 0:
        for tp in types:
            if tp is not None:
                w = tp.get("work_time", 10.0)
                if w is None:
                    w = 10.0
                if w > 0.0:
                    sumw += w
                    nw += 1
    avg_w = sumw / nw if nw else 10.0
    if avg_w <= 0.0:
        avg_w = 10.0

    # ---- Global current-cycle capacity ----
    N = len(ctx.robots)
    if N < 1:
        N = 1
    den = N - 1
    if den < 1:
        den = 1

    S = 0
    H = 0.0
    Qc = 0.0
    Qh = 0.0
    total_cap = 0.0
    for r in ctx.robots:
        c = r.count
        h = r.hours
        S += c
        H += h
        Qc += c * c
        Qh += h * h

        tp = types[r.type] if 0 <= r.type < ntypes else None
        w = 10.0
        if tp is not None:
            w = tp.get("work_time", 10.0)
            if w is None or w <= 0.0:
                w = 10.0
        dl = r.duties_left
        if dl < 0:
            dl = 0
        total_cap += dl * w

    avoid_maint = (total_cap >= R - 1e-9)

    # ---- Score available robots ----
    items = []
    min_load = None

    for r in ctx.available:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is None:
            w = 10.0
            single = 10.0
            cont = 10.0
            maint = 0.0
            charge = 0.0
            out = 0.0
            ret = 0.0
        else:
            w = tp.get("work_time", 10.0)
            single = tp.get("single_work_time", w)
            cont = tp.get("continue_max_work", single)
            maint = tp.get("maintenance_time", 0.0)
            charge = tp.get("charge_time", 0.0)
            out = tp.get("out_travel_time", 0.0)
            ret = tp.get("return_travel_time", 0.0)

        if w is None or w <= 0.0:
            w = 10.0
        if single is None or single <= 0.0:
            single = w
        if cont is None or cont <= 0.0:
            cont = single
        if maint is None or maint < 0.0:
            maint = 0.0
        if charge is None or charge < 0.0:
            charge = 0.0
        if out is None or out < 0.0:
            out = 0.0
        if ret is None or ret < 0.0:
            ret = 0.0

        M = int(cont / single)
        if M < 1:
            M = 1

        d = int(r.duties_left)
        if d < 0:
            d = 0
        if d > M:
            d = M

        progress = (M - d) / float(M)
        if progress < 0.0:
            progress = 0.0
        if progress > 1.0:
            progress = 1.0

        triggers = (d <= 1 and maint > 0.0)
        if triggers:
            ready_after = out + w + ret + maint
        else:
            ready_after = out + w + ret + charge
        can_return = (ready_after <= R + 1e-9)

        preserve = avoid_maint or (triggers and not can_return)

        if preserve:
            K = 0
        else:
            if maint > 0.0 and w > 0.0:
                req = maint / (w * den)
                K = int(req)
                if K < req - 1e-9:
                    K += 1
                if K < 1:
                    K = 1
                if K > M:
                    K = M
            else:
                K = 0

        load = r.count + r.hours / avg_w
        inc = 1.0 + w / avg_w

        cost_c = Qc + 2.0 * r.count + 1.0 - (S + 1.0) * (S + 1.0) / float(N)
        cost_h = Qh + 2.0 * r.hours * w + w * w - (H + w) * (H + w) / float(N)
        if cost_c < 0.0:
            cost_c = 0.0
        if cost_h < 0.0:
            cost_h = 0.0
        balance = cost_c + cost_h / (avg_w * avg_w + 1e-9)

        danger = 1 if (triggers and not can_return) else 0

        if min_load is None or load < min_load:
            min_load = load

        items.append((r, w, M, maint, d, progress, load, inc, balance,
                      preserve, danger, K, triggers))

    if min_load is None:
        min_load = 0.0

    scored = []
    for it in items:
        (r, w, M, maint, d, progress, load, inc, balance,
         preserve, danger, K, triggers) = it

        allowed = 0 if load <= min_load + K * inc + 1e-9 else 1
        prog_key = progress if preserve else -progress
        maint_flag = 0 if r.first_maint is None else 1

        key = (allowed, danger, prog_key, balance, load, maint_flag, r.idx)
        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    # ---- New robot type preferences ----
    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w = tp.get("work_time", 10.0)
        single = tp.get("single_work_time", w)
        cont = tp.get("continue_max_work", single)
        maint = tp.get("maintenance_time", 0.0)
        charge = tp.get("charge_time", 0.0)
        out = tp.get("out_travel_time", 0.0)
        ret = tp.get("return_travel_time", 0.0)

        if w is None or w <= 0.0:
            w = 10.0
        if single is None or single <= 0.0:
            single = w
        if cont is None or cont <= 0.0:
            cont = single
        if maint is None or maint < 0.0:
            maint = 0.0
        if charge is None or charge < 0.0:
            charge = 0.0
        if out is None or out < 0.0:
            out = 0.0
        if ret is None or ret < 0.0:
            ret = 0.0

        M = int(cont / single)
        if M < 1:
            M = 1

        inc = w + out + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0

        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc

        full = int(R / cycle) if R > 0.0 else 0
        cap = full * M * w
        rem = R - full * cycle
        pd = 0
        if rem > 0.0:
            pd = int(rem / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap += pd * w

        maxd = full * M + pd
        if maxd == 0 and R > 0.0:
            maxd = 1
            cap = w

        cover = 0 if cap >= R - 1e-9 else 1
        overshoot = cap - R if cap > R else 0.0
        if maxd == 1 and full == 0 and R > 0.0:
            overshoot = w - R if w > R else 0.0

        maint_ratio = maint / max(M * w, 1e-6)
        eff = w / max(inc + maint / float(M), 1e-6)
        fit_abs = abs(w - avg_w)

        if cover == 0:
            score = (0, fit_abs, overshoot, maint_ratio, -eff, w, k)
        else:
            score = (1, -cap, maint_ratio, -eff, fit_abs, overshoot, w, k)

        new_cand.append((score, k))

    new_cand.sort()
    new_actions = [("new", k) for _, k in new_cand]

    gt = ctx.gene_type
    if gt is not None and 0 <= gt < ntypes and types[gt] is not None and ctx.left[gt] > 0:
        if not any(a[1] == gt for a in new_actions):
            new_actions.append(("new", gt))

    actions.extend(new_actions)

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
```

