    scored = []
    for it in items:
        r, w, M, maint, d, progress, load, inc, balance = it

        preserve = (maint > 0.0 and R < inc + maint + 1e-9)

        if preserve:
            K = 0
        else:
            if maint > 0.0 and w > 0.0:
                den = Nrob - 1
                if den < 1:
                    den = 1
                req = maint / (w * den)
                K = int(req)
                if K < req - 1e-9:
                    K += 1
                if K < 1:
                    K = 1
                if K > M:
                    K = M
            else:
                K = 0

        allowed = 1 if load <= min_load + K * inc + 1e-9 else 0
        danger = 1 if (d <= 1 and R < inc + maint + 1e-9) else 0
        maint_flag = 0 if r.first_maint is None else 1
        ttm = d * inc

        if preserve:
            overlap = 1 if (d <= 1 and maint_now > 0 and healthy_avail > 0) else 0
            time_key = -ttm
            key = (
                1 if danger else 0,
                0 if allowed else 1,
                overlap,
                -ttm,
                balance,
                maint_flag,
                r.idx,
            )
        else:
            if maint_now > 0 and healthy_avail > 0:
                until = maint_end - t
                if until > R:
                    until = R
                if d <= 1:
                    overlap = 2
                elif ttm + 1e-9 >= until:
                    overlap = 0
                else:
                    overlap = 1
            else:
                overlap = 0

            time_key = -ttm if overlap == 1 else ttm
            maint_pen = maint if d <= 1 else 0.0

            key = (
                0 if allowed else 1,
                overlap,
                danger,
                maint_pen,
                time_key,
                balance,
                load,
                maint_flag,
                r.idx,
            )

        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w = float(tp.get("work_time", 10.0) or 10.0)
        single = float(tp.get("single_work_time", w) or w)
        cont = float(tp.get("continue_max_work", single) or single)
        maint = float(tp.get("maintenance_time", 0.0) or 0.0)
        charge = float(tp.get("charge_time", 0.0) or 0.0)
        out = float(tp.get("out_travel_time", 0.0) or 0.0)
        ret = float(tp.get("return_travel_time", 0.0) or 0.0)

        if w <= 0.0:
            w = 10.0
        if single <= 0.0:
            single = w
        if cont <= 0.0:
            cont = single
        if maint < 0.0:
            maint = 0.0

        M = int(cont / single)
        if M < 1:
            M = 1

        inc = w + out + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0

        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc

        full = int(R / cycle) if R > 0.0 else 0
        cap_k = full * M * w
        rem = R - full * cycle
        pd = 0
        if rem > 0.0:
            pd = int(rem / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap_k += pd * w

        maxd = full * M + pd
        if maxd == 0 and R > 0.0:
            maxd = 1
            cap_k = w

        cover = 0 if cap_k >= R - 1e-9 else 1
        overshoot = cap_k - R if cap_k > R else 0.0
        if maxd == 1 and full == 0 and R > 0.0:
            overshoot = w - R if w > R else 0.0

        maint_ratio = maint / max(M * w, 1e-6)
        eff = w / max(inc + maint / float(M), 1e-6)
        fit_abs = abs(w - avg_w)

        if cover == 0:
            score = (0, fit_abs, overshoot, maint_ratio, -eff, w, k)
        else:
            score = (1, -cap_k, maint_ratio, -eff, fit_abs, overshoot, w, k)

        new_cand.append((score, k))

    new_cand.sort()
    new_actions = [("new", k) for _, k in new_cand]

    gt = ctx.gene_type
    if gt is not None and 0 <= gt < ntypes and types[gt] is not None and ctx.left[gt] > 0:
        if not any(a[1] == gt for a in new_actions):
            new_actions.append(("new", gt))

    if cap < R - 1e-9 and maint_now > 0 and healthy_avail == 0 and ctx.available and new_actions:
        actions = [new_actions[0]] + actions + new_actions[1:]
    else:
        actions.extend(new_actions)

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
```

The rule keeps the load/maintenance-phase scoring but adds awareness of robots already in maintenance: while one is busy, it avoids triggering another maintenance by preferring available robots with more duties left and lower progress, and it softly favors opening robots of already-used types to reuse tools. It also uses a combined count/hour load in the final phase for better balance.

```python
def rule(ctx):
    R = ctx.remaining
    T = ctx.T
    t = ctx.t
    types = ctx.types
    ntypes = len(types)

    def params(tp):
        wt = float(tp.get("work_time", 10.0) or 10.0)
        single = float(tp.get("single_work_time", wt) or wt)
        cmax = float(tp.get("continue_max_work", wt) or wt)
        maint = float(tp.get("maintenance_time", 0.0) or 0.0)
        charge = float(tp.get("charge_time", 0.0) or 0.0)
        out = float(tp.get("out_travel_time", 0.0) or 0.0)
        ret = float(tp.get("return_travel_time", 0.0) or 0.0)
        if wt <= 0.0:
            wt = 10.0
        if single <= 0.0:
            single = wt
        if cmax <= 0.0:
            cmax = single
        if maint < 0.0:
            maint = 0.0
        if charge < 0.0:
            charge = 0.0
        if out < 0.0:
            out = 0.0
        if ret < 0.0:
            ret = 0.0
        return wt, single, cmax, maint, charge, out, ret

    robots = ctx.robots if ctx.robots else []

    sum_wt = 0.0
    cnt_wt = 0
    opened_by_type = [0] * ntypes
    maint_busy = False
    for r in robots:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is not None:
            wt, _, _, _, _, _, _ = params(tp)
            sum_wt += wt
            cnt_wt += 1
        else:
            sum_wt += 10.0
            cnt_wt += 1
        if 0 <= r.type < ntypes:
            opened_by_type[r.type] += 1
        if r.ready is not None and r.ready > t + 1e-9:
            if r.duties_left <= 0 or r.budget <= 1e-9:
                maint_busy = True

    avg_wt = sum_wt / cnt_wt if cnt_wt else 10.0
    if avg_wt <= 0.0:
        avg_wt = 10.0

    max_maint = 0.0
    for tp in types:
        if tp is not None:
            _, _, _, maint, _, _, _ = params(tp)
            if maint > max_maint:
                max_maint = maint

    n_robots = len(robots)
    Ncur = n_robots if n_robots > 1 else 2
    den = Ncur - 1
    if den < 1:
        den = 1

    avail = ctx.available
    avail_min_count = None
    for r in avail:
        if avail_min_count is None or r.count < avail_min_count:
            avail_min_count = r.count
    if avail_min_count is None:
        avail_min_count = 0

    final_phase = R <= 1.1 * avg_wt + 1e-9
    long_phase = R > max_maint + 2.0 * avg_wt + 1e-9

    items = []
    min_load = None

    for r in avail:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is not None:
            wt, single, cmax, maint, charge, out, ret = params(tp)
        else:
            wt = 10.0
            single = 10.0
            cmax = 10.0
            maint = 0.0
            charge = 0.0
            out = 0.0
            ret = 0.0

        M = int(cmax / single) if single > 0.0 else 1
        if M < 1:
            M = 1

        d = r.duties_left
        if d < 0:
            d = 0

        progress = (M - d) / float(M)
        if progress < 0.0:
            progress = 0.0
        if progress > 1.0:
            progress = 1.0

        load = r.count + r.hours / avg_wt
        inc = 1.0 + wt / avg_wt

        preserve = (maint > 0.0 and R < maint)

        if preserve:
            K = 0
        else:
            if maint > 0.0 and wt > 0.0:
                req = maint / (wt * den)
                K = int(req)
                if K < req - 1e-9:
                    K += 1
                if K < 1:
                    K = 1
                if K > M:
                    K = M
            else:
                K = 0

        danger = 0
        if preserve and d <= 1:
            danger = 1

        items.append((r, wt, M, K, load, inc, progress, preserve,
                      maint, danger, out, ret, charge))
        if min_load is None or load < min_load:
            min_load = load

    if min_load is None:
        min_load = 0.0

    scored = []

    for it in items:
        r, wt, M, K, load, inc, progress, preserve, maint, danger, out, ret, charge = it

        allowed = 0 if load <= min_load + K * inc + 1e-9 else 1
        maint_flag = 0 if r.first_maint is None else 1

        if preserve:
            prog_key = progress
        else:
            if maint_busy:
                prog_key = progress
            else:
                prog_key = -progress

        busy_risk = 1 if (maint_busy and r.duties_left <= 1) else 0

        if final_phase:
            key = (danger,
                   load,
                   -r.duties_left,
                   r.idx)
        else:
            risk = 0
            if r.duties_left <= 1:
                after = t + wt + out + ret + charge
                if after + maint + wt > T + 1e-9:
                    risk = 1

            if long_phase:
                cap = int(0.5 * M)
                if cap < 1:
                    cap = 1
                excess = r.count - avail_min_count - cap
                if excess < 0:
                    excess = 0

                if maint_busy:
                    key = (busy_risk, allowed, danger, excess, prog_key,
                           maint_flag, load, -r.duties_left, r.idx)
                else:
                    if allowed == 0:
                        key = (0, danger, excess, prog_key, maint_flag,
                               load, -r.duties_left, r.idx)
                    else:
                        key = (1, danger, excess, load, prog_key,
                               maint_flag, -r.duties_left, r.idx)
            else:
                if maint_busy:
                    key = (busy_risk, allowed, danger, risk, prog_key,
                           maint_flag, load, -r.duties_left, r.idx)
                else:
                    if allowed == 0:
                        key = (0, danger, risk, prog_key, maint_flag,
                               load, -r.duties_left, r.idx)
                    else:
                        key = (1, danger, risk, load, prog_key,
                               maint_flag, -r.duties_left, r.idx)

        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    new_cand = []

    for k, tp in enumerate(types):
        if tp is None:
            continue
        if ctx.left[k] <= 0:
            continue

        wt, single, cmax, maint, charge, out, ret = params(tp)

        M = int(cmax / single) if single > 0.0 else 1
        if M < 1:
            M = 1

        inc = out + wt + ret + charge
        if inc <= 0.0:
            inc = wt if wt > 0.0 else 1.0

        exp_duties = R / inc if R > 0.0 else 1.0
        if exp_duties < 1.0:
            exp_duties = 1.0

        if exp_duties >= M and maint > 0.0:
            eff_time = inc + maint / float(M)
        else:
            eff_time = inc

        efficiency = wt / eff_time if eff_time > 0.0 else 0.0

        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc

        full = int(R / cycle) if R > 0.0 else 0
        cap = full * M * wt
        rem = R - full * cycle

        if rem > 0.0:
            pd = int((rem + charge) / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap += pd * wt

        if R > 0.0:
            eff_cap = cap if cap < R else R
        else:
            eff_cap = 0.0

        overshoot = wt - R if R > 0.0 and wt > R else 0.0
        maint_ratio = maint / float(M * wt) if M * wt > 0.0 else 0.0
        util = (M * wt) / cycle if cycle > 0.0 else 0.0

        opened = opened_by_type[k] if 0 <= k < ntypes else 0
        new_type = 0 if opened > 0 else 1

        new_cand.append((overshoot, -efficiency + 0.05 * new_type,
                         -eff_cap, maint_ratio, -util, wt, k))

    new_cand.sort()
    new_actions = [("new", x[-1]) for x in new_cand]

    gt = ctx.gene_type
    valid_gt = (gt is not None and 0 <= gt < ntypes
                and types[gt] is not None and ctx.left[gt] > 0)

    if valid_gt:
        if not new_actions:
            new_actions = [("new", gt)]
        elif new_actions[0][1] != gt:
            new_actions = [new_actions[0], ("new", gt)] + [
                a for a in new_actions[1:] if a[1] != gt
            ]
    else:
        if not new_actions:
            for k, tp in enumerate(types):
                if tp is not None and ctx.left[k] > 0:
                    new_actions = [("new", k)]
                    break

    actions.extend(new_actions)

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes
                and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break

        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
