The rule uses a different central signal: **coverage slack and maintenance recycling** rather than pure load balancing. It first checks whether the opened fleet can still cover the horizon; if there is slack it protects near-maintenance robots and balances load, but if capacity is tight it preferentially uses a robot whose imminent maintenance can finish in time and return with a fresh budget, thereby recycling capacity. New-robot type choice is based on the remaining capacity **deficit**, preferring the dominate existing type when that type can fill the deficit, otherwise maximizing added capacity.

```python
def rule(ctx):
    types = ctx.types
    ntypes = len(types)
    R = float(ctx.remaining)
    T = float(ctx.T)
    t = float(ctx.t)
    eps = 1e-9

    def params(tp):
        if tp is None:
            w = 10.0
            s = 10.0
            cm = 10.0
            maint = 0.0
            charge = 0.0
            out = 0.0
            ret = 0.0
        else:
            w = tp.get("work_time", 10.0)
            s = tp.get("single_work_time", w)
            cm = tp.get("continue_max_work", s)
            maint = tp.get("maintenance_time", 0.0)
            charge = tp.get("charge_time", 0.0)
            out = tp.get("out_travel_time", 0.0)
            ret = tp.get("return_travel_time", 0.0)

        if w is None or w <= 0.0:
            w = 10.0
        if s is None or s <= 0.0:
            s = w
        if cm is None or cm <= 0.0:
            cm = s
        if maint is None or maint < 0.0:
            maint = 0.0
        if charge is None or charge < 0.0:
            charge = 0.0
        if out is None or out < 0.0:
            out = 0.0
        if ret is None or ret < 0.0:
            ret = 0.0

        M = int(cm / s) if s > 0.0 else 1
        if M < 1:
            M = 1
        return w, s, cm, maint, charge, out, ret, M

    def cap_type(k, H):
        if k < 0 or k >= ntypes or types[k] is None or H <= 0.0:
            return 0.0
        w, s, cm, maint, charge, out, ret, M = params(types[k])
        inc = out + w + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0
        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc
        full = int(H / cycle) if H > 0.0 else 0
        cap = full * M * w
        rem = H - full * cycle
        if rem > 0.0:
            pd = int(rem / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap += pd * w
        return cap

    sumw = 0.0
    nw = 0
    counts = [0] * ntypes

    for r in ctx.robots:
        k = r.type
        tp = types[k] if 0 <= k < ntypes else None
        if tp is not None:
            w = params(tp)[0]
            counts[k] += 1
        else:
            w = 10.0
        sumw += w
        nw += 1

    if nw == 0:
        for tp in types:
            if tp is not None:
                sumw += params(tp)[0]
                nw += 1

    avg_w = sumw / nw if nw else 10.0
    if avg_w <= 0.0:
        avg_w = 10.0

    opened = len(ctx.robots)
    dominant = -1
    if opened > 0:
        best = 0
        for k, c in enumerate(counts):
            if types[k] is not None and c > best:
                best = c
                dominant = k

    fleet_cap = float(ctx.capacity)
    cycle_cap = 0.0
    for r in ctx.robots:
        k = r.type
        tp = types[k] if 0 <= k < ntypes else None
        w = params(tp)[0] if tp is not None else 10.0
        d = int(r.duties_left)
        if d < 0:
            d = 0
        cycle_cap += d * w

    shortage = fleet_cap < R - eps
    local_short = cycle_cap < R - eps

    items = []
    for r in ctx.available:
        k = r.type
        tp = types[k] if 0 <= k < ntypes else None
        if tp is not None:
            w, s, cm, maint, charge, out, ret, M = params(tp)
        else:
            w = 10.0
            M = 1
            maint = 0.0
            charge = 0.0
            out = 0.0
            ret = 0.0

        d = int(r.duties_left)
        if d < 0:
            d = 0

        needs_maint = d <= 1 and maint > 0.0
        if needs_maint:
            next_ready = t + out + w + ret + maint
        else:
            next_ready = t + out + w + ret + charge

        future_cap = 0.0
        can_return = False
        danger = 0
        if needs_maint:
            can_return = next_ready + w <= T + eps
            if next_ready < T:
                future_cap = cap_type(k, T - next_ready)
            if next_ready + w > T + eps:
                danger = 1
        else:
            can_return = next_ready <= T + eps

        load = r.count + r.hours / avg_w
        excess = w - R if w > R else 0.0

        items.append((r, w, M, d, needs_maint, maint, next_ready,
                      future_cap, can_return, danger, load, excess))

    if shortage or local_short:
        scored = []
        for it in items:
            (r, w, M, d, needs_maint, maint, next_ready,
             future_cap, can_return, danger, load, excess) = it

            recycle = 1 if (needs_maint and can_return and future_cap > eps) else 0
            if recycle:
                key = (0, -future_cap, danger, excess, load, -d, next_ready, r.idx)
            else:
                cat = 1 if not needs_maint else 2
                key = (cat, danger, excess, -d, load, next_ready, r.idx)
            scored.append((key, r))
        scored.sort(key=lambda x: x[0])
    else:
        scored = []
        for it in items:
            (r, w, M, d, needs_maint, maint, next_ready,
             future_cap, can_return, danger, load, excess) = it

            if needs_maint:
                key = (1, danger, 0 if can_return else 1,
                       next_ready, excess, load, r.idx)
            else:
                key = (0, excess, load, -d, next_ready, r.idx)
            scored.append((key, r))
        scored.sort(key=lambda x: x[0])

    actions = [("reuse", r) for _, r in scored]

    deficit = R - fleet_cap
    if deficit < 0.0:
        deficit = 0.0

    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w, s, cm, maint, charge, out, ret, M = params(tp)
        cap = cap_type(k, R)

        inc = out + w + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0
        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc

        eff = (M * w) / cycle if cycle > 0.0 else 0.0
        maint_ratio = maint / (M * w) if M * w > 0.0 else 0.0
        fit_abs = abs(w - avg_w)
        over = w - R if w > R else 0.0

        if opened <= 0:
            if cap >= deficit - eps:
                score = (0, -cap, -eff, maint_ratio, over, w, k)
            else:
                score = (1, -cap, -eff, maint_ratio, over, w, k)
        else:
            dom = 0 if k == dominant else 1
            if deficit > eps:
                if cap >= deficit - eps:
                    score = (0, dom, fit_abs, -eff,
                             maint_ratio, over, cap - deficit, -cap, k)
                else:
                    score = (1, -cap, -eff, dom, fit_abs,
                             maint_ratio, over, k)
            else:
                score = (0, dom, fit_abs, over, -eff,
                         -cap, maint_ratio, k)

        new_cand.append((score, k))

    new_cand.sort()
    new_actions = [("new", k) for _, k in new_cand]

    gt = ctx.gene_type
    valid_gt = (gt is not None and 0 <= gt < ntypes
                and types[gt] is not None and ctx.left[gt] > 0)

    if valid_gt:
        if not new_actions:
            new_actions = [("new", gt)]
        elif new_actions[0][1] != gt:
            filtered = [a for a in new_actions if a[1] != gt]
            if filtered:
                new_actions = [filtered[0], ("new", gt)] + filtered[1:]
            else:
                new_actions = [("new", gt)]

    actions.extend(new_actions)

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes
                and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
```

The improved rule keeps the original maintenance-aware reuse logic but fixes the end-of-horizon handling: it avoids unnecessary “danger” penalties when a duty already finishes the horizon, adds a final-phase fit term that prefers available robots whose work length leaves a representable remainder, and makes new-robot type choice avoid bad remainder leftovers near the end. These changes reduce wasteful extra openings and improve balance without disturbing the long-horizon staggering behaviour.

```python
def rule(ctx):
    R = float(ctx.remaining)
    T = float(ctx.T)
    t = float(ctx.t)
    types = ctx.types
    ntypes = len(types)

    def gcd2(a, b):
        if b == 0:
            return a
        return gcd2(b, a % b)

    def params(tp):
        wt = float(tp.get("work_time", 10.0) or 10.0)
        single = float(tp.get("single_work_time", wt) or wt)
        cmax = float(tp.get("continue_max_work", wt) or wt)
        maint = float(tp.get("maintenance_time", 0.0) or 0.0)
        charge = float(tp.get("charge_time", 0.0) or 0.0)
        out = float(tp.get("out_travel_time", 0.0) or 0.0)
        ret = float(tp.get("return_travel_time", 0.0) or 0.0)
        if wt <= 0.0:
            wt = 10.0
        if single <= 0.0:
