        if progress < 0.0:
            progress = 0.0
        if progress > 1.0:
            progress = 1.0

        if avoid_maint:
            key = (
                danger,
                1 if trigger else 0,
                0 if allowed else 1,
                progress,
                balance,
                r.count,
                overshoot,
                r.idx,
            )
        else:
            if maint_now == 0:
                trigger_safe = 1 if (trigger and danger == 0) else 0
                maint_rank = -maint if trigger_safe else 0.0
                key = (
                    0 if trigger_safe else 1,
                    maint_rank,
                    danger,
                    time_to_maint,
                    0 if allowed else 1,
                    balance,
                    load,
                    overshoot,
                    r.idx,
                )
            else:
                key = (
                    danger,
                    1 if trigger else 0,
                    0 if allowed else 1,
                    progress,
                    balance,
                    load,
                    overshoot,
                    r.idx,
                )

        scored.append((key, r))

    scored.sort(key=lambda entry: entry[0])
    actions = [("reuse", r) for key, r in scored]

    # Deficit-aware new-robot type ordering.
    cap_now = ctx.capacity
    if cap_now < 0.0:
        cap_now = 0.0
    deficit = R - cap_now
    if deficit < 0.0:
        deficit = 0.0

    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w = float(tp.get("work_time", 10.0) or 10.0)
        single = float(tp.get("single_work_time", w) or w)
        cont = float(tp.get("continue_max_work", single) or single)
        maint = float(tp.get("maintenance_time", 0.0) or 0.0)
        charge = float(tp.get("charge_time", 0.0) or 0.0)
        out = float(tp.get("out_travel_time", 0.0) or 0.0)
        ret = float(tp.get("return_travel_time", 0.0) or 0.0)

        if w <= 0.0:
            w = 10.0
        if single <= 0.0:
            single = w
        if cont <= 0.0:
            cont = single
        if maint < 0.0:
            maint = 0.0

        M = int(cont / single) if single > 0.0 else 1
        if M < 1:
            M = 1

        inc_time = w + out + ret + charge
        if inc_time <= 0.0:
            inc_time = w
        if inc_time <= 0.0:
            inc_time = 1.0

        cycle = M * inc_time + maint
        if cycle <= 0.0:
            cycle = inc_time

        full = int(R / cycle) if R > 0.0 else 0
        cap = full * M * w
        rem = R - full * cycle
        if rem < 0.0:
            rem = 0.0

        pd = 0
        if rem > 0.0:
            pd = int(rem / inc_time)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap += pd * w

        maxd = full * M + pd
        if maxd == 0 and R > 0.0:
            maxd = 1
            cap = w

        if R >= M * inc_time:
            eff_time = inc_time + maint / float(M)
        else:
            eff_time = inc_time
        eff = w / eff_time if eff_time > 0.0 else 0.0

        if deficit > 0.0:
            if cap >= deficit - eps:
                over_def = cap - deficit
                score = (0, over_def, abs(w - avg_w), -eff, k)
            else:
                score = (1, -cap, -eff, abs(w - avg_w), k)
        else:
            over_R = w - R if w > R + eps else 0.0
            score = (0, over_R, abs(w - avg_w), -eff, -w, k)

        new_cand.append((score, k))

    new_cand.sort(key=lambda entry: entry[0])
    for score, k in new_cand:
        actions.append(("new", k))

    if not actions:
        k = ctx.gene_type
        ok = (k is not None and 0 <= k < ntypes and
              types[k] is not None and ctx.left[k] > 0)
        if not ok:
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is None:
            for i, tp in enumerate(types):
                if tp is not None:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
