The rule keeps a simple round-robin load balance (duties plus normalized duty hours) while explicitly avoiding unnecessary maintenance when the currently opened robots still have enough remaining-cycle capacity to finish the horizon. When maintenance is unavoidable, it prioritizes robots whose maintenance can return before the horizon, but guards against taking too many robots down at once. New-robot type selection estimates the minimum number of that type needed to cover the remaining horizon continuously, then breaks ties by duty-cycle efficiency and capacity.

```python
def rule(ctx):
    types = ctx.types
    ntypes = len(types)
    R = ctx.remaining
    if R is None or R < 0.0:
        R = 0.0

    # Average duty length, used to normalize hours against duty counts.
    sumw = 0.0
    nw = 0
    for r in ctx.robots:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is not None:
            w = tp.get("work_time", 10.0)
            if w is None or w <= 0.0:
                w = 10.0
            sumw += w
            nw += 1
    if nw == 0:
        for tp in types:
            if tp is not None:
                w = tp.get("work_time", 10.0)
                if w is None or w <= 0.0:
                    w = 10.0
                sumw += w
                nw += 1
    avg_w = sumw / nw if nw else 10.0
    if avg_w <= 0.0:
        avg_w = 10.0

    N = len(ctx.robots)
    if N < 1:
        N = 1
    U = len(ctx.robots) - len(ctx.available)
    if U < 0:
        U = 0

    # Capacity in the current maintenance cycle.  If this covers the
    # remaining horizon, avoid triggering maintenance needlessly.
    total_cap = 0.0
    for r in ctx.robots:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        w = 10.0
        if tp is not None:
            w = tp.get("work_time", 10.0)
            if w is None or w <= 0.0:
                w = 10.0
        d = int(r.duties_left)
        if d < 0:
            d = 0
        total_cap += d * w
    avoid_maint = (total_cap >= R - 1e-9)

    items = []
    for r in ctx.available:
        tp = types[r.type] if 0 <= r.type < ntypes else None
        if tp is None:
            w = 10.0
            single = 10.0
            cont = 10.0
            maint = 0.0
            charge = 0.0
            out = 0.0
            ret = 0.0
        else:
            w = tp.get("work_time", 10.0)
            single = tp.get("single_work_time", w)
            cont = tp.get("continue_max_work", single)
            maint = tp.get("maintenance_time", 0.0)
            charge = tp.get("charge_time", 0.0)
            out = tp.get("out_travel_time", 0.0)
            ret = tp.get("return_travel_time", 0.0)

            if w is None or w <= 0.0:
                w = 10.0
            if single is None or single <= 0.0:
                single = w
            if cont is None or cont <= 0.0:
                cont = single
            if maint is None or maint < 0.0:
                maint = 0.0
            if charge is None or charge < 0.0:
                charge = 0.0
            if out is None or out < 0.0:
                out = 0.0
            if ret is None or ret < 0.0:
                ret = 0.0

        M = int(cont / single) if single > 0.0 else 1
        if M < 1:
            M = 1

        d = int(r.duties_left)
        if d < 0:
            d = 0
        if d > M:
            d = M

        triggers = (d <= 1 and maint > 0.0)
        if triggers:
            ready_after = out + w + ret + maint
        else:
            ready_after = out + w + ret + charge
        can_return = (ready_after <= R + 1e-9)

        # Lower priority value is preferred.
        if avoid_maint:
            pri = 2 if triggers else 0
        else:
            if triggers:
                if can_return:
                    if N > 1 and U + 1 >= N:
                        pri = 2
                    else:
                        pri = 0
                else:
                    pri = 3
            else:
                pri = 1

        # Incremental increase of the combined count/hour squared load.
        balance = (2.0 * r.count + 1.0) + (2.0 * r.hours * w + w * w) / (avg_w * avg_w + 1e-9)

        # If maintenance is avoidable, prefer more remaining budget.
        # If maintenance is needed, prefer robots closer to it.
        dkey = -d if avoid_maint else d

        key = (pri, balance, dkey, r.idx)
        items.append((key, r))

    items.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in items]

    # Rank new robot types by an estimate of how many of that type would be
    # needed to cover the remaining horizon continuously.
    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w = tp.get("work_time", 10.0)
        single = tp.get("single_work_time", w)
        cont = tp.get("continue_max_work", single)
        maint = tp.get("maintenance_time", 0.0)
        charge = tp.get("charge_time", 0.0)
        out = tp.get("out_travel_time", 0.0)
        ret = tp.get("return_travel_time", 0.0)

        if w is None or w <= 0.0:
