        if M < 1:
            M = 1

        inc = out + w + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0

        maint_ratio = maint / (M * w) if M * w > 0.0 else 0.0
        eff = w / (inc + maint / float(M)) if (inc + maint / float(M)) > 0.0 else 0.0

        cycle = M * inc + maint
        if cycle <= 0.0:
