        full = int(R / cycle) if R > 0.0 else 0
        rem = R - full * cycle
        pd = 0
        if rem > 0.0:
            pd = int(rem / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0

        maxd = full * M + pd
        if maxd < 1 and R > 0.0:
            maxd = 1
        cap = maxd * w
        if cap <= 0.0:
            cap = w

        over = 1 if w > R + 1e-9 else 0
        over_amt = w - R if w > R else 0.0

        if R <= w + 1e-9:
            n_est = 1
        else:
            n_cov = int((inc + w - 1e-9) / w) if w > 0.0 else 1
            if n_cov < 1:
                n_cov = 1

            denom = M * w
            n_no_maint = int((R + denom - 1e-9) / denom) if denom > 0.0 else 1
            if n_no_maint < 1:
                n_no_maint = 1

            if n_cov >= n_no_maint:
                n_est = n_cov
            else:
                inc_eff = inc + maint / float(M)
                n_steady = int((inc_eff + w - 1e-9) / w) if w > 0.0 else 1
                if n_steady < 1:
                    n_steady = 1
                n_cap = int((R + cap - 1e-9) / cap) if cap > 0.0 else 1
                if n_cap < 1:
                    n_cap = 1
                n_est = n_steady if n_steady > n_cap else n_cap

        score = (over, over_amt, n_est, -eff, -cap, -w, maint_ratio, abs(w - avg_w), k)
        new_cand.append((score, k))

    new_cand.sort(key=lambda x: x[0])
    new_actions = [("new", k) for _, k in new_cand]
    actions.extend(new_actions)

    gt = ctx.gene_type
    if gt is not None and 0 <= gt < ntypes and types[gt] is not None and ctx.left[gt] > 0:
        if not any(a[1] == gt for a in new_actions):
            actions.append(("new", gt))

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
