        other_by_next = 0
        other_by_after = 0
        next_ready_min = T + R + 1000000.0

        for info in infos:
            rr = info[0]
            if rr is r:
                continue
            rr_ready = info[9]
            can_cover = (info[7] > 0) or info[8]
            if can_cover:
                if rr_ready <= next_t + eps:
                    other_by_next += 1
                    if rr_ready < next_ready_min:
                        next_ready_min = rr_ready
                if rr_ready <= ready_after + eps:
                    other_by_after += 1

        safe = 0 if next_t >= T - eps or other_by_next >= 1 else 1
        maint_risk = 0
        if triggers and ready_after < T - eps and other_by_after < 1:
            maint_risk = 1

        load = r.count + r.hours / avg_w
        cost_c = Qc + 2.0 * r.count + 1.0 - (S + 1.0) * (S + 1.0) / float(Nrob)
        cost_h = Qh + 2.0 * r.hours * w + w * w - (H + w) * (H + w) / float(Nrob)
        if cost_c < 0.0:
            cost_c = 0.0
        if cost_h < 0.0:
            cost_h = 0.0
        balance = cost_c + cost_h / (avg_w * avg_w + 1e-9)

        if not refresh_need:
            if triggers:
                rp = 2
            else:
                rp = 0
        else:
            if triggers:
                if returns and safe == 0 and maint_risk == 0:
                    rp = 0
                else:
                    rp = 2
            else:
                rp = 1

        if triggers:
            d_key = maint
        else:
            d_key = -d

        if other_by_next > 0:
            margin = next_t - next_ready_min
        else:
            margin = -1000000.0
        margin_key = -margin

        key = (rp, safe, maint_risk, balance, d_key, load, margin_key, r.idx)
        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    new_cand = []
    for k, tp in enumerate(types):
        if tp is None or ctx.left[k] <= 0:
            continue

        w, single, cont, maint, charge, out, ret, M = params(tp)
        inc = w + out + ret + charge
        if inc <= 0.0:
            inc = w if w > 0.0 else 1.0

        cycle = M * inc + maint
        if cycle <= 0.0:
            cycle = inc

        full = int(R / cycle) if R > 0.0 else 0
        cap = full * M * w
        rem = R - full * cycle
        pd = 0
        if rem > 0.0:
            pd = int(rem / inc)
            if pd > M:
                pd = M
            if pd < 0:
                pd = 0
            cap += pd * w

        maxd = full * M + pd if rem > 0.0 else full * M
        if maxd == 0 and R > 0.0:
            maxd = 1
            cap = w

        cover = 0 if cap >= R - eps else 1
        overshoot = cap - R if cap > R else 0.0
        if maxd == 1 and full == 0 and R > 0.0:
            overshoot = w - R if w > R else 0.0

        maint_ratio = maint / max(M * w, 1e-6)

        exp_duties = R / inc if inc > 0.0 else 1.0
        if exp_duties < 1.0:
            exp_duties = 1.0
        if exp_duties >= M and maint > 0.0:
            eff_time = inc + maint / float(M)
        else:
            eff_time = inc
        eff = w / eff_time if eff_time > 0.0 else 0.0

        fit_abs = abs(w - avg_w)

        if R <= 0.0:
            score = (0, fit_abs, -eff, -w, k)
        elif w > R + eps:
            score = (2, w, -eff, fit_abs, k)
        elif cover == 0:
            score = (0, fit_abs, overshoot, -eff, maint_ratio, -w, k)
        else:
            score = (1, -cap, -eff, fit_abs, maint_ratio, overshoot, -w, k)

        new_cand.append((score, k))

    new_cand.sort()
    for _, k in new_cand:
        actions.append(("new", k))

    if not actions:
        k = ctx.gene_type
        if not (k is not None and 0 <= k < ntypes and types[k] is not None and ctx.left[k] > 0):
            k = None
            for i, tp in enumerate(types):
                if tp is not None and ctx.left[i] > 0:
                    k = i
                    break
        if k is not None:
            actions = [("new", k)]
        else:
            actions = [("new", ctx.gene_type)]

    return actions
